type Pt=(f64,f64);
#[derive(Clone,Copy)] struct Port { p:Pt,d:Pt }
fn num(v:&Value,k:&str)->f64 {v[k].as_f64().unwrap_or(0.0)}
fn dist(a:Pt,b:Pt)->f64 {(a.0-b.0).hypot(a.1-b.1)}
fn port(n:&Value,s:&str,end:bool)->Port {let(x,y,w,h)=(num(n,"x"),num(n,"y"),num(n,"w"),num(n,"h"));let sign=if end{-1.0}else{1.0};let(p,d)=match s {"t"=>((x+w/2.0,y-10.0),(0.0,-sign)),"b"=>((x+w/2.0,y+h+10.0),(0.0,sign)),"l"=>((x-10.0,y+h/2.0),(-sign,0.0)),_=>((x+w+10.0,y+h/2.0),(sign,0.0))};Port{p,d}}
fn round(p:Vec<Pt>,r:f64)->Vec<Pt>{if p.len()<3||r<=0.0{return p}let mut out=vec![p[0]];for i in 1..p.len()-1{let(a,b,c)=(p[i-1],p[i],p[i+1]);let(l1,l2)=(dist(a,b),dist(b,c));if l1<0.01||l2<0.01{out.push(b);continue}let rr=r.min(l1/2.0).min(l2/2.0);let s=(b.0+(a.0-b.0)*rr/l1,b.1+(a.1-b.1)*rr/l1);let e=(b.0+(c.0-b.0)*rr/l2,b.1+(c.1-b.1)*rr/l2);out.push(s);for j in 1..=8{let t=j as f64/8.0;let u=1.0-t;out.push((u*u*s.0+2.0*u*t*b.0+t*t*e.0,u*u*s.1+2.0*u*t*b.1+t*t*e.1));}}out.push(*p.last().unwrap());out}
fn angled(a:Port,b:Port,r:f64)->Vec<Pt>{let mut p=vec![a.p];let(ah,bh)=(a.d.0!=0.0,b.d.0!=0.0);if ah&&bh{if(a.p.1-b.p.1).abs()>0.5{let x=(a.p.0+b.p.0)/2.0;p.extend([(x,a.p.1),(x,b.p.1)]);}}else if !ah&&!bh{if(a.p.0-b.p.0).abs()>0.5{let y=(a.p.1+b.p.1)/2.0;p.extend([(a.p.0,y),(b.p.0,y)]);}}else if ah{p.push((b.p.0,a.p.1));}else{p.push((a.p.0,b.p.1));}p.push(b.p);round(p,r)}
fn curve(a:Port,b:Port)->Vec<Pt>{let dx=b.p.0-a.p.0;let dy=b.p.1-a.p.1;let d=dx.hypot(dy).max(1.0);let arm=|run:f64|if run>8.0{24.0_f64.max(d*0.42).min(run*0.5)}else{60.0_f64.min(28.0_f64.max(d*0.3))};let ka=arm(a.d.0*dx+a.d.1*dy);let kb=arm(b.d.0*dx+b.d.1*dy);let c=(a.p.0+a.d.0*ka,a.p.1+a.d.1*ka);let e=(b.p.0-b.d.0*kb,b.p.1-b.d.1*kb);(0..=64).map(|i|{let t=i as f64/64.0;let u=1.0-t;(u*u*u*a.p.0+3.0*u*u*t*c.0+3.0*u*t*t*e.0+t*t*t*b.p.0,u*u*u*a.p.1+3.0*u*u*t*c.1+3.0*u*t*t*e.1+t*t*t*b.p.1)}).collect()}
fn rect_dist(p:Pt,n:&Value)->f64{let(x,y,w,h)=(num(n,"x"),num(n,"y"),num(n,"w"),num(n,"h"));(x-p.0).max(0.0).max(p.0-x-w).hypot((y-p.1).max(0.0).max(p.1-y-h))}
fn lengths(p:&[Pt])->Vec<f64>{let mut l=vec![0.0];for q in p.windows(2){l.push(l.last().unwrap()+dist(q[0],q[1]));}l}
impl Scene<'_>{
 pub(crate) fn route_layout_edges(&self,nodes:&[Value],edges:&[Value])->Result<Vec<Vec<Pt>>,String>{
 let mut ends=Vec::new();for e in edges{let i=e["i"].as_u64().ok_or("edge source required")? as usize;let j=e["j"].as_u64().ok_or("edge target required")? as usize;let a=nodes.get(i).ok_or("edge source outside node list")?;let b=nodes.get(j).ok_or("edge target outside node list")?;ends.push((port(a,e["si"].as_str().unwrap_or("r"),false),port(b,e["sj"].as_str().unwrap_or("l"),true)));}
 if self.theme.name=="daylight"||self.theme.name=="blueprint"{let r=if self.theme.name=="daylight"{22.0}else{4.0};return Ok(ends.into_iter().enumerate().map(|(i,(a,b))|edges[i]["line"].as_array().map(|line|line.iter().map(|p|(num(p,"x"),num(p,"y"))).collect()).unwrap_or_else(||angled(a,b,r))).collect())}
 let mut groups:BTreeMap<(usize,String),Vec<(usize,bool,usize)>>=BTreeMap::new();for(i,e)in edges.iter().enumerate(){if e.get("line").is_some(){continue}let a=e["i"].as_u64().unwrap() as usize;let b=e["j"].as_u64().unwrap() as usize;groups.entry((a,e["si"].as_str().unwrap_or("r").into())).or_default().push((i,false,b));groups.entry((b,e["sj"].as_str().unwrap_or("l").into())).or_default().push((i,true,a));}
 let mut uses=vec![1usize;edges.len()];for((node,side),mut group)in groups{let n=group.len();for g in &group{uses[g.0]=uses[g.0].max(n);}if n<2{continue}let vertical=side=="l"||side=="r";let axis=if vertical{"y"}else{"x"};let extent=if vertical{"h"}else{"w"};group.sort_by(|a,b|(num(&nodes[a.2],axis)+num(&nodes[a.2],extent)/2.0).total_cmp(&(num(&nodes[b.2],axis)+num(&nodes[b.2],extent)/2.0)));let step=34.0_f64.min(num(&nodes[node],extent)*0.6/(n-1) as f64);for(idx,(edge,end,_))in group.into_iter().enumerate(){let off=(idx as f64-(n-1) as f64/2.0)*step;let p=if end{&mut ends[edge].1}else{&mut ends[edge].0};if vertical{p.p.1+=off}else{p.p.0+=off}}}
 let bases:Vec<Vec<Pt>>=ends.into_iter().map(|(a,b)|curve(a,b)).collect();let mut out=Vec::new();for(i,base)in bases.iter().enumerate(){let edge=&edges[i];if let Some(line)=edge["line"].as_array(){out.push(line.iter().map(|p|(num(p,"x"),num(p,"y"))).collect());continue}if self.theme.name!="signal"{out.push(base.clone());continue}let a=edge["i"].as_u64().unwrap() as usize;let b=edge["j"].as_u64().unwrap() as usize;let mut room=999.0_f64;for p in &base[(base.len() as f64*0.15).floor() as usize..=(base.len() as f64*0.85).ceil() as usize]{for(k,n)in nodes.iter().enumerate(){if k!=a&&k!=b&&n["t"]!="band"{room=room.min(rect_dist(*p,n));}}for(j,other)in bases.iter().enumerate(){if j==i{continue}for q in other.iter().take((other.len() as f64*0.88).ceil() as usize).skip((other.len() as f64*0.12).floor() as usize).step_by(2){room=room.min(dist(*p,*q));}}}
 out.push(twist(base,room,uses[i],nodes,a,b,self.w,self.h));}Ok(out)
 }
}
fn twist(base:&[Pt],room:f64,siblings:usize,nodes:&[Value],a:usize,b:usize,w:f64,h:f64)->Vec<Pt>{let l=lengths(base);let total=*l.last().unwrap();if total==0.0{return base.to_vec()}let mut amp=24.0_f64.min(total*0.08).min(room*0.4)/(siblings as f64).sqrt();let r=34.0_f64.min(room/2.6).min(total*0.1);let tangent=|s:f64|{let i=(s*(base.len()-2) as f64).round() as usize;(base[i+1].1-base[i].1).atan2(base[i+1].0-base[i].0)};let mut turn=(tangent(0.2)-tangent(0.8)).abs();if turn>PI{turn=TAU-turn}let looping=siblings==1&&total>=240.0&&r>=18.0&&turn<0.35;if amp<3.0&&!looping{return base.to_vec()}let span=if looping{0.07_f64.max(0.2_f64.min(0.7*PI*r/total))}else{0.0};let cycles=if total>520.0{2.0}else{1.0};let mut sign=1.0;if looping{let mid=base.len()/2;let p=base[mid];let q=base[mid+1];let tx=q.0-p.0;let ty=q.1-p.1;let length=tx.hypot(ty).max(1.0);let probe=|s:f64|{let p=(p.0-ty/length*s*2.0*r,p.1+tx/length*s*2.0*r);if p.0<64.0||p.0>w-64.0||p.1<170.0||p.1>h-40.0{return 0.0}nodes.iter().enumerate().filter(|(k,_)|*k!=a&&*k!=b).map(|(_,n)|rect_dist(p,n)).fold(999.0_f64,f64::min)};if probe(1.0)<probe(-1.0){sign=-1.0}amp*=0.5;}
 let angles:Vec<f64>=(0..base.len()).map(|i|{let p=base[i.saturating_sub(1)];let q=base[(i+1).min(base.len()-1)];(q.1-p.1).atan2(q.0-p.0)}).collect();let radius:Vec<f64>=(0..base.len()).map(|i|{if i==0||i==base.len()-1{return 999.0}let mut da=(angles[i+1]-angles[i-1]).abs();if da>PI{da=TAU-da}if da<1e-4{999.0}else{(l[i+1]-l[i-1])/da}}).collect();(0..base.len()).map(|i|{let cap=radius[i.saturating_sub(6)..=(i+6).min(base.len()-1)].iter().copied().fold(999.0_f64,f64::min)*0.4;let s=l[i]/total;let p=base[i.saturating_sub(1)];let q=base[(i+1).min(base.len()-1)];let tx=q.0-p.0;let ty=q.1-p.1;let length=tx.hypot(ty).max(1.0);let ux=tx/length;let uy=ty/length;let mut normal=amp.min(cap)*(TAU*cycles*s).sin()*(PI*s).sin().powi(2);let mut along=0.0;if looping{let u=(s-(0.5-span))/(2.0*span);if u>0.0&&u<1.0{let phi=TAU*u*u*(3.0-2.0*u);along+=r*phi.sin();normal+=sign*r*(1.0-phi.cos());}}(base[i].0+ux*along-uy*normal,base[i].1+uy*along+ux*normal)}).collect()}
